// Échoue si une page de docs/ n'apparaît pas dans la navigation (sidebars.mjs).
// Les pages des dossiers listés automatiquement (« autogenerated ») sont couvertes d'office.
import {readdirSync, statSync} from 'node:fs';
import {join, relative, sep} from 'node:path';
import sidebars from '../sidebars.mjs';

const docsDir = 'docs';

function listerPages(dir) {
  return readdirSync(dir).flatMap((nom) => {
    const chemin = join(dir, nom);
    if (statSync(chemin).isDirectory()) return listerPages(chemin);
    return /\.mdx?$/.test(nom) ? [relative(docsDir, chemin).split(sep).join('/').replace(/\.mdx?$/, '')] : [];
  });
}

const ids = new Set();
const dossiersAuto = [];
function parcourir(item) {
  if (typeof item === 'string') ids.add(item);
  else if (Array.isArray(item)) item.forEach(parcourir);
  else if (item.type === 'doc') ids.add(item.id);
  else if (item.type === 'autogenerated') dossiersAuto.push(item.dirName);
  else if (item.items) parcourir(item.items);
}
Object.values(sidebars).forEach(parcourir);

const oubliees = listerPages(docsDir).filter(
  (page) => !ids.has(page) && !dossiersAuto.some((d) => page.startsWith(`${d}/`)),
);
if (oubliees.length) {
  console.error(`Pages absentes de la navigation (sidebars.mjs) :\n  ${oubliees.join('\n  ')}`);
  process.exit(1);
}
console.log('Navigation : toutes les pages de docs/ sont présentes.');
